//! The Tauri native host's `measureText` behind a C ABI, so that Deno and Bun
//! measure text with the very code the reference CLI uses: the same font
//! database (the CLI's bundled faces first, then system faces), fallback,
//! rustybuzz shaping and ink bounds.
//!
//! `fonts.rs` is generated by build-js-measure.sh from the `fonts` list in
//! markgraf/cli/native/main.rs, so both hosts load identical faces.

use std::cell::RefCell;
use std::ffi::{c_char, CString};
use tauri_native_host::{FontAsset, TextMeasurer};

include!("fonts.rs");

thread_local! {
    // The native host also builds its font database on the first measurement.
    static MEASURER: RefCell<Option<TextMeasurer>> = const { RefCell::new(None) };
    static FAILURE: RefCell<CString> = RefCell::new(CString::default());
}

/// Measures `text` in the CSS `font` shorthand and writes width, ascent and
/// descent to `metrics`. Returns null on success, or the host's error message,
/// valid until the next call on this thread.
///
/// # Safety
/// `font` and `text` point to `*_length` bytes of UTF-8; `metrics` to three f64.
#[no_mangle]
pub unsafe extern "C" fn markgraf_measure_text(
    font: *const u8,
    font_length: usize,
    text: *const u8,
    text_length: usize,
    metrics: *mut f64,
) -> *const c_char {
    let font = unsafe { string(font, font_length) };
    let text = unsafe { string(text, text_length) };
    match measure(&font, &text) {
        Ok(measured) => {
            let metrics = unsafe { std::slice::from_raw_parts_mut(metrics, 3) };
            metrics.copy_from_slice(&[measured.width, measured.ascent, measured.descent]);
            std::ptr::null()
        }
        Err(message) => failure(message),
    }
}

/// The message Rust's `std::io::Error` gives an OS error number, e.g.
/// "No such file or directory (os error 2)", valid until the next call.
#[no_mangle]
pub extern "C" fn markgraf_os_error(code: i32) -> *const c_char {
    failure(std::io::Error::from_raw_os_error(code).to_string())
}

fn measure(font: &str, text: &str) -> Result<tauri_native_host::TextMetrics, String> {
    MEASURER.with(|measurer| {
        let mut measurer = measurer.borrow_mut();
        if measurer.is_none() {
            *measurer = Some(TextMeasurer::new(&fonts()).map_err(|error| error.to_string())?);
        }
        let measurer = measurer.as_ref().expect("measurer initialised above");
        measurer.measure(font, text).map_err(|error| error.to_string())
    })
}

unsafe fn string(bytes: *const u8, length: usize) -> String {
    let bytes = if length == 0 { &[][..] } else { unsafe { std::slice::from_raw_parts(bytes, length) } };
    String::from_utf8_lossy(bytes).into_owned()
}

fn failure(message: String) -> *const c_char {
    let message = CString::new(message.replace('\0', "\u{fffd}")).expect("NUL bytes were replaced");
    FAILURE.with(|failure| {
        *failure.borrow_mut() = message;
        failure.borrow().as_ptr()
    })
}
